/**
 * Damped springs, shared by CSS and JS motion. A world's manifest names its spring once
 * ({ stiffness, damping, mass }); motion/react animates with it directly, and the world's
 * tokens.css carries the same curve as `--ease-spring: linear(…)` with `--dur-spring` (the
 * settle time), generated by `springToLinear` and checked against the manifest in tests.
 */

export type SpringPreset = { stiffness: number; damping: number; mass: number };

/** Damping ratio: < 1 overshoots (bouncy), 1 is critically damped, > 1 creeps in. */
export function dampingRatio({ stiffness, damping, mass }: SpringPreset): number {
  return damping / (2 * Math.sqrt(stiffness * mass));
}

/** Progress (0 → 1, may overshoot) of a spring released from rest at 0 towards 1, at `t` seconds. */
export function springAt(preset: SpringPreset, t: number): number {
  const { stiffness: k, mass: m } = preset;
  const w0 = Math.sqrt(k / m);
  const zeta = dampingRatio(preset);
  if (Math.abs(zeta - 1) < 1e-6) return 1 - Math.exp(-w0 * t) * (1 + w0 * t);
  if (zeta < 1) {
    const wd = w0 * Math.sqrt(1 - zeta * zeta);
    return 1 - Math.exp(-zeta * w0 * t) * (Math.cos(wd * t) + ((zeta * w0) / wd) * Math.sin(wd * t));
  }
  const s = w0 * Math.sqrt(zeta * zeta - 1);
  const r1 = -zeta * w0 + s;
  const r2 = -zeta * w0 - s;
  return 1 + (r2 * Math.exp(r1 * t) - r1 * Math.exp(r2 * t)) / (r1 - r2);
}

/** Seconds until the spring stays within `epsilon` of its target. */
export function settleTime(preset: SpringPreset, epsilon = 0.002): number {
  const step = 1 / 600;
  let lastOutside = 0;
  for (let t = 0; t < 10; t += step) {
    if (Math.abs(springAt(preset, t) - 1) > epsilon) lastOutside = t;
  }
  return Math.min(10, lastOutside + step);
}

const round = (n: number, digits: number) => {
  const p = 10 ** digits;
  return Math.round(n * p) / p;
};

/**
 * The spring as a CSS `linear()` easing over its settle time, simplified to the points needed
 * to stay within `tolerance` of the curve. Returns the easing and the duration it was sampled over.
 */
export function springToLinear(preset: SpringPreset, tolerance = 0.004): { easing: string; durationMs: number } {
  const duration = settleTime(preset);
  const samples = 240;
  const pts = Array.from({ length: samples + 1 }, (_, i) => {
    const x = i / samples;
    return { x, y: i === samples ? 1 : springAt(preset, x * duration) };
  });
  // Ramer–Douglas–Peucker on the (x, y) polyline.
  const keep = new Set([0, samples]);
  const simplify = (a: number, b: number) => {
    let worst = -1;
    let at = -1;
    const pa = pts[a]!;
    const pb = pts[b]!;
    for (let i = a + 1; i < b; i++) {
      const p = pts[i]!;
      const yLine = pa.y + ((pb.y - pa.y) * (p.x - pa.x)) / (pb.x - pa.x);
      const d = Math.abs(p.y - yLine);
      if (d > worst) {
        worst = d;
        at = i;
      }
    }
    if (worst > tolerance && at > 0) {
      keep.add(at);
      simplify(a, at);
      simplify(at, b);
    }
  };
  simplify(0, samples);
  const stops = [...keep]
    .sort((a, b) => a - b)
    .map((i, n, all) => {
      const p = pts[i]!;
      if (n === 0) return '0';
      if (n === all.length - 1) return '1';
      return `${round(p.y, 3)} ${round(p.x * 100, 1)}%`;
    });
  return { easing: `linear(${stops.join(', ')})`, durationMs: Math.round(duration * 1000) };
}

/** Reads a CSS `linear()` easing back into (x, y) points, for tests and tooling. */
export function parseLinear(easing: string): { x: number; y: number }[] {
  const body = /^linear\((.*)\)$/.exec(easing.trim())?.[1];
  if (!body) return [];
  const parts = body.split(',').map((s) => s.trim().split(/\s+/));
  return parts.map(([y, x], i) => ({
    y: Number(y),
    x: x === undefined ? (i === 0 ? 0 : i === parts.length - 1 ? 1 : NaN) : Number(x.replace('%', '')) / 100,
  }));
}
